/**
 * Hand-authored signature kits — part A (Naruto, Sasuke, Sakura, Kakashi,
 * Rock Lee, Gaara, Itachi, Pain, Madara, Boruto).
 *
 * Every move below has individually authored frame data, damage, reach and
 * behaviour — these are NOT generated from an archetype multiplier. Names refer
 * to well-known techniques for a private prototype; all artwork, effects and
 * audio are original placeholders generated by this project.
 */

import { mk, projectile } from './ability-schema.js';

/**
 * Wire a ground chain / air chain and return the id map.
 * `basics`, `air` etc. are explicit per-move option objects, so each fighter
 * ends up with genuinely different numbers rather than a scaled template.
 */
export function fighterKit(p, cfg) {
  const ids = {
    basicCombos: [], airCombos: [], heavy: `${p}_heavy`, launcher: `${p}_launcher`,
    dashAttack: `${p}_dash`, throwAttack: `${p}_throw`, guardCounter: `${p}_gc`,
    abilities: [], ultimate: `${p}_ultimate`,
  };

  cfg.basics.forEach((m, i) => {
    const id = `${p}_b${i + 1}`;
    ids.basicCombos.push(id);
    const next = i + 1 < cfg.basics.length ? [`${p}_b${i + 2}`] : [];
    mk(id, {
      category: 'basic',
      chainInto: [...next, ids.heavy, ids.launcher],
      ...m,
    });
  });

  cfg.air.forEach((m, i) => {
    const id = `${p}_a${i + 1}`;
    ids.airCombos.push(id);
    const next = i + 1 < cfg.air.length ? [`${p}_a${i + 2}`] : [];
    mk(id, {
      category: 'aerial', airOk: true, groundOk: false,
      chainInto: next, ...m,
    });
  });

  mk(ids.heavy, { category: 'heavy', soundId: 'sfx_hit_heavy', ...cfg.heavy });
  mk(ids.launcher, { category: 'launcher', launch: true, soundId: 'sfx_launch', ...cfg.launcher });
  mk(ids.dashAttack, { category: 'dash', ...cfg.dash });
  mk(ids.throwAttack, { category: 'throw', unblockable: true, guardDamage: 0, animationId: 'throw', soundId: 'sfx_hit_heavy', ...cfg.throw });
  mk(ids.guardCounter, { category: 'counter', invulnerability: { start: 0, end: 0.16 }, ...cfg.gc });

  for (const [suffix, opts] of Object.entries(cfg.jutsu)) {
    const id = `${p}_${suffix}`;
    ids.abilities.push(id);
    mk(id, opts);
  }

  mk(ids.ultimate, {
    category: 'ultimate', cutIn: true, slowMoFinish: true,
    soundId: 'sfx_ultimate', effectId: 'ultimate_burst',
    invulnerability: { start: 0, end: 0.28 },
    ...cfg.ultimate,
  });

  return ids;
}

